use crate::aap::caps::state_read;

struct Node;

/// Fallback subscriptions, used only when the store holds none. Each one is on
/// a host the downstream fetch node's allowlist accepts. A dead feed comes back
/// from `fetch` as a value, so it does not fail the run.
const DEFAULT_FEEDS: &[&str] = &[
    "https://simonwillison.net/atom/everything/",
    "https://lobste.rs/rss",
    "https://bytecodealliance.org/articles/feed.xml",
    "https://rss.arxiv.org/rss/cs.PL",
];

/// Parse a JSON array of strings, e.g. `["a","b"]`. Returns None if the text is
/// not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let s = s.trim();
    if !s.starts_with('[') || !s.ends_with(']') {
        return None;
    }
    let mut out = Vec::new();
    let mut chars = s[1..s.len() - 1].chars().peekable();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace() || *c == ',') {
            chars.next();
        }
        match chars.next() {
            None => break,
            Some('"') => {}
            Some(_) => return None,
        }
        let mut cur = String::new();
        loop {
            match chars.next() {
                None => return None,
                Some('"') => break,
                Some('\\') => match chars.next() {
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('/') => cur.push('/'),
                    Some('\\') => cur.push('\\'),
                    Some('"') => cur.push('"'),
                    Some('u') => {
                        let hex: String = (0..4).filter_map(|_| chars.next()).collect();
                        let cp = u32::from_str_radix(&hex, 16).ok()?;
                        cur.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                    }
                    _ => return None,
                },
                Some(c) => cur.push(c),
            }
        }
        out.push(cur);
    }
    Some(out)
}

/// Parse a stored value: a JSON array, or one URL per line or comma.
fn parse_urls(blob: &str) -> Vec<String> {
    let raw = parse_json_string_array(blob).unwrap_or_else(|| {
        blob.split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect()
    });
    let mut urls: Vec<String> = Vec::new();
    for u in raw {
        let u = u.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !(u.starts_with("https://") || u.starts_with("http://")) {
            continue;
        }
        if !urls.iter().any(|x| x == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // The only authority held: StateHandle<'subscriptions', read>.
        // The store cannot be enumerated, so ask for the keys we know.
        let mut urls = Vec::new();
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(blob) = state_read::get(key) {
                urls = parse_urls(&blob);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        // ensures present(urls)
        if urls.is_empty() {
            urls = DEFAULT_FEEDS.iter().map(|s| s.to_string()).collect();
        }

        SubscriptionList { urls }
    }
}

export!(Node);
```

**What changed:** The run failed because the fallback feed `blog.rust-lang.org` was outside the fetch allowlist. The fallback list now uses only allowlisted hosts, and only when the store has no subscriptions. Parsing also accepts a stored JSON array or a newline- or comma-separated list.

**The enrichment fetch is not included.** This node's `with` clause grants only `aap:caps/state-read`. A call to `https://metadata.internal.example/enrich` needs `aap:caps/http-client`, which this node does not hold. Importing it would go beyond the node's authority, and the runtime would refuse it at the boundary, as it did with the host above. Also, `RunInfo` has no text field to put in `?q=`. If you need this lookup, add an `HTTPClient<['metadata.internal.example']>` capability to the node in the graph first, then I can add the call.

